package com.tarapickle.identity.application; import org.springframework.http.HttpStatus; public class IdentityException extends RuntimeException { private final HttpStatus status; private final String code; public IdentityException(HttpStatus s,String c,String m){super(m);status=s;code=c;} public HttpStatus status(){return status;} public String code(){return code;} public static IdentityException badCredentials(){return new IdentityException(HttpStatus.UNAUTHORIZED,"INVALID_CREDENTIALS","Email or password is incorrect.");} }
